// 1. Standardize the text output from the different parsers
let text = "";
if ($json.data) text = $json.data;
else if ($json.text) text = $json.text;
else text = JSON.stringify($json);

// 2. Fetch the filename from the Search node
let filename = $('Search files and folders2').item.json.name || "";

// 3. Determine if this is the SI or BL file based on the filename
let docType = filename.includes("SI") ? "SI" : "BL";

// 4. Extract the email_id directly from the filename (e.g., email_004_SI.txt -> email_004)
let emailId = filename.split("_SI")[0].split("_BL")[0];

return { 
  email_id: emailId,
  document_type: docType,
  filename: filename,
  document_text: text
};

// 1. Safely parse the JSON string from the LLM's 'text' output
let extractedData = {};
try {
  extractedData = JSON.parse($json.text);
} catch (error) {
  // Fallback just in case the parser already converted it to an object
  extractedData = $json; 
}

// 2. Re-attach the email_id and doc_type using the correct node name
return {
  email_id: $('Normalize & Tag Data').item.json.email_id,
  document_type: $('Normalize & Tag Data').item.json.document_type,
  extracted_fields: extractedData
};

let result = [];

for (let item of $input.all()) {
  let data = item.json;
  let emailId = data.email_id;
  let fields = data.extracted_fields || {};

  if (data.document_type === "BL") {
    result.push({
      json: {
        "_routing_tag": "BL",
        "Email No.": emailId,
        "BL Shipper ": fields.shipper || "",
        "BL Consignee": fields.consignee || "",
        "BL Notify Party": fields.notify_party || "",
        "BL Port of Loading": fields.port_of_loading || "",
        "Bl Port of Discharge": fields.port_of_discharge || "",
        "BL Container Count": fields.container_count || "",
        "BL Gross Weight (KG)": fields.gross_weight_kg || ""
      }
    });
  } else if (data.document_type === "SI") {
    result.push({
      json: {
        "_routing_tag": "SI",
        "Email No.": emailId,
        "SI Shipper ": fields.shipper || "",
        "SI Consignee": fields.consignee || "",
        "SI Notify Party": fields.notify_party || "",
        "SI Port of Loading": fields.port_of_loading || "",
        "SI Port of Discharge": fields.port_of_discharge || "",
        "SI Container Count": fields.container_count || "",
        "SI Gross Weight (KG)": fields.gross_weight_kg || ""
      }
    });
  }
}

return result;
